using static StrataLint.Scribe.DefinitionDsl;
using static StrataLint.Scribe.FormulaDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Algebra.StateApproximation;

internal sealed class StateApproximationS3QuantumAlgebraStateApproximationReconstructedStateGNSDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Pure GNS for original real states", H("Pure GNS for original real states"), Blocks(
        Paragraph(Text("Let A be an arbitrary nontrivial unital complex C*-algebra in Type u with PartialOrder A and StarOrderedRing A. A real state beta is an arbitrary real linear functional on selfAdjoint A, positive on original nonnegative elements, with beta(1)=1. Continuity is a consequence of positivity and normalization. It has a unique positive normalized continuous complex linear extension phi to the same A, agreeing with beta on every original self-adjoint element. Restriction and extension give an affine equivalence of the whole real and complex state spaces. If beta is extreme in the whole original real state space, there are a complete complex Hilbert space H in Type u, a unital star representation pi of A and a unit cyclic vector Omega. For every a in A, phi(a)=inner(Omega,pi(a)Omega); for every original self-adjoint a the moment is beta(a). Every bounded operator commuting with pi(A) is a complex scalar multiple of the identity. Continuity, purity, interpolation and a GNS representation are not premises.")),
        Describe.Lean(DescribeId.Create("statement0"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/ReconstructedStateGNS.state_abs_le"),
            H("state_abs_le"), StatementSource.FromAuthor(Disp(Statement0())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Positivity on y-x makes beta monotone. The self-adjoint order bounds neg_algebraMap_norm_le_self and le_algebraMap_norm_self place a between minus norm(a) times 1 and norm(a) times 1. Apply monotonicity and beta(1)=1 to these bounds, then use abs_le."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement1"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/ReconstructedStateGNS.realCLM_norm_le"),
            H("realCLM_norm_le"), StatementSource.FromAuthor(Disp(Statement1())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The estimate state_abs_le bounds the original real linear functional by norm(a) with constant 1. LinearMap.mkContinuous_norm_le therefore bounds the operator norm of realCLM by 1; continuity is obtained from positivity and normalization rather than assumed of beta."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement2"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/ReconstructedStateGNS.state_moment"),
            H("state_moment"), StatementSource.FromAuthor(Disp(Statement2())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Regard phi as the positive map positiveMap phi hphi. Positive maps preserve self-adjointness, so phi(a) is a real complex number for self-adjoint a. Complex.re_eq_ofReal_of_isSelfAdjoint identifies it with the embedded real part, which is exactly restriction phi a."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement3"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/ReconstructedStateGNS.restriction_mem"),
            H("restriction_mem"), StatementSource.FromAuthor(Disp(Statement3())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For a positive original self-adjoint a, positivity of phi and Complex.nonneg_iff give nonnegativity of its real part. At the unit, phi(1)=1 implies that the restriction has value 1. These are precisely the two conditions of IsRealState."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement4"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/ReconstructedStateGNS.ext_selfAdjoint"),
            H("ext_selfAdjoint"), StatementSource.FromAuthor(Disp(Statement4())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Decompose an arbitrary a with realPart_add_I_smul_imaginaryPart into a self-adjoint real part plus i times a self-adjoint imaginary part. Complex linearity and the assumed equality on both parts imply equality at a, and continuous-linear-map extensionality finishes."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement5"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/ReconstructedStateGNS.exists_extension"),
            H("exists_extension"), StatementSource.FromAuthor(Disp(Statement5())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Apply exists_positive_extensions_norm_additive to realCLM beta, obtaining positive p,n with beta=Re(p-n) on the self-adjoint part and norm(realCLM)=Re(p(1))+Re(n(1)). Normalization and realCLM_norm_le force Re(n(1))=0. PositiveContinuousLinearMap.ofReal_opNorm_eq_map_one then makes n zero. Self-adjoint preservation identifies p(a) with the embedded beta(a), including p(1)=1, so p is the required positive normalized complex extension."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement6"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/ReconstructedStateGNS.extension_moment"),
            H("extension_moment"), StatementSource.FromAuthor(Disp(Statement6())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The extension is chosen from exists_extension, whose second conclusion specifies every original self-adjoint moment. Its choose_spec therefore supplies this equality for each a. This records the exact moments of the chosen extension, without adding a continuity assumption on the starting beta."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement7"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/ReconstructedStateGNS.restriction_extension"),
            H("restriction_extension"), StatementSource.FromAuthor(Disp(Statement7())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Evaluate both real linear maps at an arbitrary self-adjoint a. By extension_moment the complex value of the extension is the embedded beta(a); taking its real part and using Complex.ofReal_re recovers beta(a). Extensionality gives equality of maps."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement8"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/ReconstructedStateGNS.extension_restriction"),
            H("extension_restriction"), StatementSource.FromAuthor(Disp(Statement8())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Use ext_selfAdjoint to compare the two complex states after Subtype.ext. On each self-adjoint a, extension_moment equals the embedded restriction of phi, while state_moment identifies the latter with phi(a). Thus extension after restriction recovers the original complex state."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement9"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/ReconstructedStateGNS.extension_affine_iff"),
            H("extension_affine_iff"), StatementSource.FromAuthor(Disp(Statement9())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For the forward implication, evaluate the real affine identity at a self-adjoint element, embed the resulting real equality into the complex numbers, and use extension_moment and ext_selfAdjoint. For the reverse implication apply the real linear map restriction to the complex affine identity and simplify with restriction_extension. The coefficients s,t are arbitrary real numbers, without convexity assumptions."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement10"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/ReconstructedStateGNS.extreme_forward"),
            H("extreme_forward"), StatementSource.FromAuthor(Disp(Statement10())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Use mem_extremePoints_iff_left. Pull the two endpoints of a target open segment back through e.symm, and use haff to pull back its same positive coefficients and sum-one relation. Extremality of x forces the first preimage to equal x; applying e transports that equality to the target endpoint."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement11"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/ReconstructedStateGNS.extreme_equiv"),
            H("extreme_equiv"), StatementSource.FromAuthor(Disp(Statement11())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Apply extreme_forward first to e with haff. For the converse, the same affine equivalence for e.symm follows by substituting inverse images into haff and reversing the equivalence. A second application of extreme_forward and the inverse laws returns extremality of x."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement12"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/ReconstructedStateGNS.real_complex_extreme_iff"),
            H("real_complex_extreme_iff"), StatementSource.FromAuthor(Disp(Statement12())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The inverse identities restriction_extension and extension_restriction define realComplexEquiv, and extension_affine_iff preserves every real affine relation. Applying extreme_equiv to these data transports extremality in the whole real state space to extremality in the whole complex state space."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement13"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/ReconstructedStateGNS.provider_mem"),
            H("provider_mem"), StatementSource.FromAuthor(Disp(Statement13())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("State.toPositiveLinearMap makes every nonnegative algebra element have nonnegative image, and State.apply_one gives the value 1 at the unit. Consequently the underlying continuous linear functional satisfies exactly complexStateSpace's positivity and normalization conditions."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement14"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/ReconstructedStateGNS.provider_stateSpace_eq"),
            H("provider_stateSpace_eq"), StatementSource.FromAuthor(Disp(Statement14())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Unpack membership in the range defining Physicslib4.GNS.stateSpace. Each such underlying functional lies in complexStateSpace by provider_mem. Conversely provider bundles any member of complexStateSpace into a State with that same functional, giving the opposite inclusion."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement15"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/ReconstructedStateGNS.original_moment"),
            H("original_moment"), StatementSource.FromAuthor(Disp(Statement15())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("originalState is provider applied to extension, and provider leaves the continuous linear functional unchanged. Therefore extension_moment supplies the original beta moment directly; the bundling adds only positivity and normalization proofs."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement16"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/ReconstructedStateGNS.original_extreme_iff"),
            H("original_extreme_iff"), StatementSource.FromAuthor(Disp(Statement16())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Rewrite State.IsExtremePoint using mem_extremePoints_iff_isExtremePoint, then identify the provider state space with complexStateSpace using provider_stateSpace_eq. The remaining real-to-complex equivalence is real_complex_extreme_iff, so the original whole-state-space extremality is retained."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement17"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/ReconstructedStateGNS.original_pure_iff"),
            H("original_pure_iff"), StatementSource.FromAuthor(Disp(Statement17())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Use isPure_iff_isExtremePoint to replace purity of originalState by its convex extremality. The equivalence original_extreme_iff then identifies this with extremality of beta in the whole original real state space."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement18"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/ReconstructedStateGNS.actual_pure_gns"),
            H("actual_pure_gns"), StatementSource.FromAuthor(Disp(Statement18())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Bundle beta as a real state and use original_pure_iff to obtain purity of originalState. gns_construction gives a same-universe cyclic representation and its exact moments; evaluating the unit moment and State.apply_one gives norm(Omega)=1. ext_selfAdjoint proves uniqueness of the complex extension from its prescribed moments, and isIrreducible_of_isPure gives the scalar commutant conclusion. No representation, density or separability hypothesis is supplied as an input."))), DescribeRole.Theorem))));

