    private static Formula N(string name) => Seq(Operatorname, Grp(FormulaDsl.Id(name)));

    private static Formula Call(string name, params Formula[] arguments) => new Formula.Apply(N(name), [.. arguments]);
    private static Formula All(string name, Formula type, Formula body) => new Formula.Bind(FormulaQuantifier.ForAll, FormulaIdentifier.Create(name), type, body);
    private static Formula Ex(string name, Formula type, Formula body) => new Formula.Bind(FormulaQuantifier.Exists, FormulaIdentifier.Create(name), type, body);
    private static Formula Equal(Formula x, Formula y) => new Formula.Relation(x, FormulaRelationOperator.Equal, y);
    private static Formula And(Formula x, Formula y) => new Formula.Logic(Seq(Open, x, Close), FormulaLogicOperator.And, Seq(Open, y, Close));
    private static Formula Imp(Formula x, Formula y) => new Formula.Logic(Seq(Open, x, Close), FormulaLogicOperator.Implies, Seq(Open, y, Close));
    private static Formula Member(Formula x, Formula s) => new Formula.Relation(x, FormulaRelationOperator.MemberOf, s);
    private static Formula Norm(Formula x) => new Formula.Norm(x);
    private static Formula Apply(Formula f, params Formula[] xs) => new Formula.Apply(f, [.. xs]);
    private static Formula SA() => Call("selfAdjoint", FormulaDsl.Id("A"));
