    private static Formula RealLinear() => Call("LinearMap", Real(), SA(), Real());
    private static Formula Coe(Formula x) => Seq(Open, x, Colon, FormulaDsl.Id("A"), Close);
    private static Formula ComplexCoe(Formula x) => Seq(Open, x, Colon, Complex(), Close);
    private static Formula Class(string name, Formula x) => Seq(OpenBracket, Call(name, x), CloseBracket, Sp);
    private static Formula Algebra(Formula body) => All("A", Type("u"), Seq(
