        Class("PartialOrder", FormulaDsl.Id("A")), Class("StarOrderedRing", FormulaDsl.Id("A")), body));
    private static Formula Pure(Formula b) => Member(b, Call("extremePoints", Real(), Call("realStateSpace", FormulaDsl.Id("A"))));
    private static Formula Reading(Formula b, Formula a) => Apply(b, a);
    private static Formula Represented(Formula a, Formula x) => Apply(Apply(FormulaDsl.Id("pi"), a), x);
    private static Formula Inner(Formula x, Formula y) => Call("inner", Complex(), x, y);
    private static Formula Product(Formula x, Formula y) => new Formula.Binary(x, FormulaBinaryOperator.Multiply, y);
